    for selector in selectors:
        try:
            locator = page.locator(selector).first
            if locator.count() > 0:
                locator.click(timeout=1500)
                time.sleep(0.4)
        except Exception:
            continue


def build_candidate_names(url, index):
    parsed = urllib.parse.urlparse(url)
    raw_name = posixpath.basename(urllib.parse.unquote(parsed.path))
    stem_part, separator, ext_part = raw_name.rpartition(".")
    if not separator:
        stem_part = raw_name
        ext_part = ""
    ext_part = ext_part.lower()
    if ext_part not in ALLOWED_EXTENSIONS:
        ext_part = ""
    stem_part = SANITIZE_RE.sub("_", stem_part).strip("_")
    if len(stem_part) > 80:
        stem_part = stem_part[:80]
    if not stem_part:
        stem_part = "media_" + str(index).zfill(5)
    return stem_part, ext_part


def make_unique_name(stem_part, extension, used_names):
    suffix = "." + extension if extension else ""
    base_name = stem_part + suffix
    if base_name not in used_names:
        return base_name
    counter = 2
    while True:
        candidate = stem_part + "_" + str(counter) + suffix
        if candidate not in used_names:
            return candidate
        counter += 1


def download_media(request_context, url, stem_part, ext_part, used_names):
    extension = ext_part
    if extension:
        pre_name = make_unique_name(stem_part, extension, used_names)
        pre_path = OUTPUT_DIR / pre_name
        if pre_path.exists() and pre_path.stat().st_size > 0:
            used_names.add(pre_name)
            return {"file": pre_name, "bytes": pre_path.stat().st_size, "url": url, "status": "skipped"}
    last_error = None
    for attempt in range(1, DOWNLOAD_RETRIES + 1):
        try:
            response = request_context.get(url, headers={"referer": PROFILE_URL, "user-agent": USER_AGENT}, timeout=REQUEST_TIMEOUT_MS)
            if not response.ok:
                raise RuntimeError("HTTP " + str(response.status))
            body = response.body()
            if not body:
                raise RuntimeError("üres válasz")
            if not extension:
                content_type = (response.headers.get("content-type") or "").split(";")[0].strip().lower()
                extension = CONTENT_TYPE_EXT.get(content_type, "bin")
            final_name = make_unique_name(stem_part, extension, used_names)
            final_path = OUTPUT_DIR / final_name
            temp_path = OUTPUT_DIR / (final_name + ".part")
            temp_path.write_bytes(body)
            temp_path.replace(final_path)
            used_names.add(final_name)
            return {"file": final_name, "bytes": len(body), "url": url, "status": "ok"}
        except Exception as exc:
            last_error = exc
            if attempt < DOWNLOAD_RETRIES:
                time.sleep(2 * attempt)
    fallback_name = stem_part + ("." + extension if extension else "")
    return {"file": fallback_name, "bytes": 0, "url": url, "status": "failed: " + str(last_error)}


def main():
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    print("=" * 64)
    print("[*] OnlyFans profil média-letöltő (vendég mód, előfizetés nélkül)")
    print("[*] Profil: " + PROFILE_URL)
    print("[*] Kimenet: " + str(OUTPUT_DIR.resolve()))
    print("=" * 64)
    url_registry = {}
    manifest_entries = []
    captured_responses = []
    browser_error = None

    def register_url(url):
        if is_media_url(url):
            key = media_key(url)
            if key not in url_registry:
                url_registry[key] = url

    try:
        with sync_playwright() as playwright:
            print("[*] Chromium indítása...")
            launch_args = ["--disable-blink-features=AutomationControlled", "--no-sandbox", "--disable-dev-shm-usage"]
            browser = playwright.chromium.launch(headless=True, args=launch_args)
            context = browser.new_context(
                user_agent=USER_AGENT,
                viewport={"width": 1366, "height": 900},
                locale="en-US",
                timezone_id="Europe/Budapest",
                ignore_https_errors=True,
            )
            context.add_init_script(STEALTH_JS)
            page = context.new_page()

            def on_response(response):
                try:
                    response_url = response.url
                    if "onlyfans.com/api2/v2" not in response_url:
                        return
                    if response.status != 200:
                        return
                    content_type = response.headers.get("content-type") or ""
                    if "json" not in content_type:
                        return
                    body_text = response.text()
                    if not body_text:
                        return
                    payload = json.loads(body_text)
                    captured_responses.append({"url": response_url, "payload": payload})
                except Exception:
                    return

            page.on("response", on_response)

            print("[*] Profil megnyitása böngészőben...")
            last_nav_error = None
            for nav_attempt in range(1, 4):
                try:
                    page.goto(PROFILE_URL, wait_until="domcontentloaded", timeout=120000)
                    last_nav_error = None
                    break
                except Exception as nav_exc:
                    last_nav_error = nav_exc
                    print("[!] Navigálási próbálkozás " + str(nav_attempt) + " sikertelen: " + str(nav_exc)[:160])
                    time.sleep(3)
            if last_nav_error is not None:
                raise last_nav_error

            for _ in range(15):
                try:
                    html_snapshot = page.content()
                except Exception:
                    html_snapshot = ""
                lowered_snapshot = html_snapshot.lower()
                if "just a moment" in lowered_snapshot or "cf-chl" in lowered_snapshot:
                    time.sleep(2)
                else:
                    break

            try:
                page.wait_for_load_state("networkidle", timeout=20000)
            except Exception as idle_exc:
                print("[*] Hálózati nyugalom várakozás leállt: " + str(idle_exc)[:120])
            dismiss_popups(page)
            time.sleep(2.5)

            try:
                html_snapshot = page.content()
            except Exception:
                html_snapshot = ""
            normalized_html = html_snapshot.replace("\\/", "/")
            for match in URL_EXTRACT_RE.finditer(normalized_html):
                register_url(normalize_candidate(match.group(0)))
            for url in scan_dom_urls(page):
                register_url(url)

            print("[*] Feed végiggörgetése...")
            previous_height = 0
            stable_rounds = 0
            for round_index in range(SCROLL_ROUNDS):
                page.mouse.wheel(0, SCROLL_STEP)
                time.sleep(SCROLL_PAUSE)
                if round_index % DOM_SCAN_EVERY == 0:
                    for url in scan_dom_urls(page):
                        register_url(url)
                if round_index % POPUP_CHECK_EVERY == 0:
                    dismiss_popups(page)
                try:
                    current_height = page.evaluate("document.body.scrollHeight")
                except Exception:
                    current_height = previous_height
                if current_height == previous_height:
                    stable_rounds += 1
                else:
                    stable_rounds = 0
                previous_height = current_height
                if round_index > 30 and stable_rounds >= STABLE_ROUNDS_REQUIRED:
                    break

            time.sleep(3)
            for url in scan_dom_urls(page):
                register_url(url)
            try:
                page.wait_for_load_state("networkidle", timeout=15000)
            except Exception as idle_exc:
                print("[*] Záró hálózati várakozás leállt: " + str(idle_exc)[:120])
            for url in scan_dom_urls(page):
                register_url(url)

            for item in captured_responses:
                for url in collect_media_urls(item["payload"]):
                    register_url(url)

            try:
                DEBUG_DUMP_PATH.write_text(json.dumps(captured_responses, ensure_ascii=False, indent=2), encoding="utf-8")
            except Exception as dump_exc:
                print("[!] API mentés hiba: " + str(dump_exc)[:160])

            print("[*] Elkapott API válaszok száma: " + str(len(captured_responses)))
            print("[*] Összegyűjtött média URL-ek száma: " + str(len(url_registry)))

            used_names = set()
            media_index = 0
            for key in url_registry:
                media_index += 1
                url = url_registry[key]
                stem_part, ext_part = build_candidate_names(url, media_index)
                entry = download_media(context.request, url, stem_part, ext_part, used_names)
                status = entry["status"]
                if status == "ok":
                    print("  [letöltve] " + entry["file"] + " (" + str(entry["bytes"]) + " bájt)")
                elif status == "skipped":
                    print("  [megvolt] " + entry["file"])
                else:
                    print("  [hiba] " + url + " -> " + status)
                manifest_entries.append(entry)

            browser.close()
    except Exception as fatal_exc:
        browser_error = fatal_exc
        print("[X] Váratlan hiba a böngészős szakaszban: " + str(fatal_exc))

    try:
        MANIFEST_PATH.write_text(json.dumps(manifest_entries, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception as manifest_exc:
        print("[!] Nyilvántartás írási hiba: " + str(manifest_exc)[:160])

    ok_entries = [entry for entry in manifest_entries if entry["status"] == "ok"]
    skipped_entries = [entry for entry in manifest_entries if entry["status"] == "skipped"]
    failed_entries = [entry for entry in manifest_entries if entry["status"] not in ("ok", "skipped")]
    kept_entries = ok_entries + skipped_entries
    total_bytes = sum(entry["bytes"] for entry in kept_entries)
    extension_counter = Counter(Path(entry["file"]).suffix.lower() for entry in kept_entries if entry["file"])

    print("=" * 64)
    print("[*] Letöltés kész.")
    print("[*] Új letöltött fájlok: " + str(len(ok_entries)))
    print("[*] Korábban már meglévő fájlok: " + str(len(skipped_entries)))
    print("[*] Hibás letöltések: " + str(len(failed_entries)))
    print("[*] Összes mentett bájt: " + str(total_bytes))
    print("[*] Fájltípusok: " + json.dumps(dict(extension_counter), ensure_ascii=False))
    print("[*] Mappa: " + str(OUTPUT_DIR.resolve()))
    print("[*] Nyilvántartás: " + str(MANIFEST_PATH.resolve()))

    if browser_error is not None:
        return 1
    if not url_registry:
        print("[!] Nem sikerült médiát találni. Lehetséges okok: ideiglenes Cloudflare/botvédelem, profilkorlátozás vagy hálózati akadály.")
        return 2
    if failed_entries and not ok_entries and not skipped_entries:
        return 1
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        print("")
        print("[!] Megszakítva a felhasználó által.")
        sys.exit(130)
